function validate([nums, value]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value in nums is an integer between -10^9 and 10^9.';
  if (!Number.isInteger(value) || value < 1 || value > 100000) return 'value is an integer between 1 and 10^5.';
  return null;
}

