function findSmallestInteger(nums, value) {
  const count = new Array(value).fill(0);
  for (const num of nums) {
    const remainder = ((num % value) + value) % value;
    count[remainder]++;
  }
  let mex = 0;
  while (count[mex % value] > 0) {
    count[mex % value]--;
    mex++;
  }
  return mex;
}

