function findSmallestInteger(nums, value) {
  const used = new Array(nums.length).fill(false);
  for (let target = 0; ; target++) {
    let found = -1;
    for (let i = 0; i < nums.length; i++) {
      if (!used[i] && (nums[i] - target) % value === 0) { found = i; break; }
    }
    if (found === -1) return target;
    used[found] = true;
  }
}

