function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8);
    const value = pick(1, 6);
    const span = rand() < 0.5 ? 10 : 40;
    return [Array.from({ length: n }, () => pick(-span, span)), value];
  }
  const n = 2000;
  const mode = rand();
  const value = mode < 0.4 ? pick(1, 60) : mode < 0.8 ? pick(100, 2500) : pick(1, 100000);
  const nums = Array.from({ length: n }, () => {
    if (rand() < 0.3) return pick(-1000000000, 1000000000);
    return pick(0, Math.min(value * 40, 1000000)) * (rand() < 0.5 ? -1 : 1);
  });
  return [nums, value];
}
